def clean(df):
    df = df.drop_duplicates().copy()
    df['Region'] = df['Region'].astype(str).str.strip().replace({'Nort': 'North'})
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    df = df[df['Quantity'] >= 1]
    return df

def answer(df):
    g = df.groupby('Region')['Quantity'].sum()
    return {k: int(v) for k, v in g.items() if pd.notna(k)}
